using System.Diagnostics;
using System.IO;
using System.Windows;
using System.Windows.Controls;
using SysAdminAssistant.Core;
using SysAdminAssistant.Infrastructure;
namespace SysAdminAssistant.Desktop;
public partial class MainWindow
{
    private UIElement DeviceConnectionButtons(Device device){var panel=new WrapPanel{Margin=new(0,0,0,12)};var current=DeviceConnections.Parse(device.ConnectionsJson);var web=UiButton("Web");var ssh=UiButton("SSH");var rdp=UiButton("RDP");var edit=UiButton("Настроить подключения");foreach(var b in new[]{web,ssh,rdp,edit})panel.Children.Add(b);edit.IsEnabled=AccessRules.Level(remote.CurrentUser,NetworkDevices.Module(device.Type))>=2;
        void Refresh(){web.IsEnabled=current.WebUrl!="";ssh.IsEnabled=current.SshHost!="";rdp.IsEnabled=current.RdpHost!="";web.ToolTip=current.WebUrl==""?"Укажите адрес Web / WebFig в настройках":current.WebUrl;ssh.ToolTip=current.SshHost==""?"SSH не настроен":current.SshHost+":"+current.SshPort;rdp.ToolTip=current.RdpHost==""?"RDP не настроен":current.RdpHost+":"+current.RdpPort;}
        void Launch(Action action){try{current.Validate();action();}catch(Exception e){AppMessageBox.Show(Window.GetWindow(panel)??this,e.Message,"Подключение",MessageBoxButton.OK,MessageBoxImage.Error);}}
        web.Click+=(_,_)=>Launch(()=>Process.Start(new ProcessStartInfo(new Uri(current.WebUrl).AbsoluteUri){UseShellExecute=true}));
        ssh.Click+=(_,_)=>Launch(()=>{var exe=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"OpenSSH","ssh.exe");if(!File.Exists(exe))throw new InvalidOperationException(global::SysAdminAssistant.Core.ProductText.Get("На этом ПК не установлен клиент OpenSSH. Установите компонент Windows «Клиент OpenSSH». На сервере мониторинга ничего устанавливать не нужно."));var pi=new ProcessStartInfo(exe){UseShellExecute=true};foreach(var a in current.SshArguments())pi.ArgumentList.Add(a);Process.Start(pi);});
        rdp.Click+=(_,_)=>Launch(()=>{var folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"SysAdminAssistant","RdpConnections");Directory.CreateDirectory(folder);foreach(var old in Directory.EnumerateFiles(folder,"connection-*.rdp")){try{if(File.GetLastWriteTimeUtc(old)<DateTime.UtcNow.AddDays(-7))File.Delete(old);}catch(IOException){}catch(UnauthorizedAccessException){}}var file=Path.Combine(folder,"connection-"+Guid.NewGuid().ToString("N")+".rdp");File.WriteAllText(file,current.RdpFile(),System.Text.Encoding.Unicode);Process.Start(new ProcessStartInfo(file){UseShellExecute=true});});
        edit.Click+=async(_,_)=>{try{var owner=Window.GetWindow(panel)??this;var f=new FormDialog(owner,"Подключения · "+device.Name,800).Toggle("webOn","Web / WebFig",current.WebUrl!="").Text("web","Полный URL · отдельный от REST API",current.WebUrl).Toggle("sshOn","SSH",current.SshHost!="").Text("sshHost","SSH · IP / DNS",current.SshHost==""?device.Host:current.SshHost).Text("sshPort","SSH · порт",current.SshPort.ToString()).Text("sshUser","SSH · логин (необязательно)",current.SshUser).Toggle("rdpOn","RDP",current.RdpHost!="").Text("rdpHost","RDP · IP / DNS",current.RdpHost==""?device.Host:current.RdpHost).Text("rdpPort","RDP · порт",current.RdpPort.ToString()).Text("rdpUser","RDP · логин / DOMAIN\\user (необязательно)",current.RdpUser).Note("Подключение идёт с этого компьютера, не через сервер и не через агент. Пароль запрашивает внешний клиент; он не попадает в команду или RDP-файл. SSH использует локальный OpenSSH, Web — браузер по умолчанию, RDP — приложение для .rdp-файлов. Проверка сертификатов и ключей SSH не отключается.");DeviceConnections Read()=>new(f.Checked("webOn")?f.Value("web").Trim():"",f.Checked("sshOn")?f.Value("sshHost").Trim():"",f.Number("sshPort",1,65535),f.Value("sshUser").Trim(),f.Checked("rdpOn")?f.Value("rdpHost").Trim():"",f.Number("rdpPort",1,65535),f.Value("rdpUser").Trim());f.Validate=()=>{var value=Read();value.Validate();if(f.Checked("webOn")&&value.WebUrl==""||f.Checked("sshOn")&&value.SshHost==""||f.Checked("rdpOn")&&value.RdpHost=="")return "Заполните адрес включённого подключения";return null;};if(f.ShowDialog()!=true)return;var next=Read();await using var db=factory.Create();var latest=await Microsoft.EntityFrameworkCore.EntityFrameworkQueryableExtensions.SingleAsync(db.Devices,d=>d.Id==device.Id);if(latest.ConnectionsJson!=device.ConnectionsJson)throw new InvalidOperationException(global::SysAdminAssistant.Core.ProductText.Get("Подключения изменены другим пользователем. Откройте карточку заново"));latest.ConnectionsJson=next.Serialize();await db.SaveChangesAsync();device.ConnectionsJson=latest.ConnectionsJson;current=next;Refresh();}catch(Exception e){AppMessageBox.Show(Window.GetWindow(panel)??this,e.Message,"Подключения");}};Refresh();return panel;
    }
}
